                         'ГБ, до 4 ГБ; 802.11n включён.',
                         'iMac (начало 2008) — Core 2 Duo 2,4 или 2,66 ГГц (только 20 дюймов), 2,8 или 3,06 ГГц; '
                         'графика Radeon HD 2400 XT (20 дюймов), HD 2600 PRO, а в 24-дюймовой — NVIDIA GeForce 8800 GS '
                         'с 512 МБ; память 1 или 2 ГБ PC2-6400 (800 МГц), до 4 ГБ.',
                         'Во всех моделях — двухслойный SuperDrive: в первых двух ревизиях 24x/24x/8x/8x/4x/2.4x '
