                               'с производства 1 сентября 1987 года.',
                               'В 512Ke стояли тот же процессор Motorola 68000 на 7,8336 МГц, тот же новый '
                               'двусторонний дисковод на 800 КБ и те же ПЗУ на 128 КБ, что и в Mac Plus, но памяти '
                               'было вдвое меньше (512 КБ) и не было порта SCSI. Сначала 512Ke выпускали в том же '
                               'бежевом цвете, что и Macintosh 128K, а позже — в платиновом, как у Macintosh SE. '
                               'Расширенная клавиатура Mac Plus была необязательной (артикул M2519).',
                               '512 КБ памяти, новые ПЗУ и дисковод на 800 КБ позволили таким Mac пользоваться новыми '
                               'возможностями: файловой системой Hierarchical File System, внешним жёстким диском '
                               'Apple HD20 через порт дисковода и (как отдельным обновлением) портом SCSI. SCSI и '
                               'дополнительную память можно было получить дорогим набором Macintosh Plus Logic Board '
                               'Kit (артикул M2518); были и более дешёвые сторонние решения, выводившие SCSI через '
                               'заднюю крышку батарейного отсека.',
                               'В поставку входили System 3.0 (3.2 после июня 1986 года, обратно совместимая с 1.0) и '
