 {'slug': 'power-macintosh-6100',
  'title': 'Power Macintosh 6100',
  'category': 'mac',
  'year': 1994,
  'emoji': '🖥️',
  'summary': 'Первый Power Macintosh начального уровня на PowerPC 601 в корпусе Quadra 610.',
  'facts': {'Кодовое название': 'Piltdown Man',
            'Разработчик': 'Apple Computer',
            'Тип': 'настольный компьютер',
            'Представлен': '14 марта 1994',
            'Процессор': 'PowerPC 601, 60 МГц (с января 1995 года — 66 МГц)',
            'Система': 'System 7.1.2'},
  'body': ['Power Macintosh 6100 с кодовым названием «Piltdown Man» (в честь пилтдаунского человека) стал первым Power '
           'Macintosh начального уровня, когда его представили 14 марта 1994 года.',
           'Само семейство Power Macintosh (позже просто Power Mac) Apple выпускала с марта 1994 по август 2006 года. '
           'Это были первые компьютеры Apple на RISC-процессорах PowerPC. Программы для процессоров Motorola 68000 на '
           'PowerPC напрямую не работали, поэтому начиная с System 7.1.2 в систему включили эмулятор 68k.'],
  'sections': [{'title': 'Особенности',
                'paragraphs': ['Сначала 6100 выпускался с процессором PowerPC 601 на 60 МГц в обычной и '
                               '«AV»-конфигурациях. В январе 1995 года появилась версия на 66 МГц. Были также варианты '
                               'Performa и Workgroup Server. Для совместимости с DOS и Windows предлагалась PC-опция: '
                               'карта NuBus с процессором Intel 486DX2 на 66 МГц.',
                               'Корпус 6100 унаследовал от Macintosh Quadra 610 и был самым плоским среди первых трёх '
                               'Power Mac. Лицевая панель делилась на три равные части. В первой были логотип Apple и '
                               'нанесённое краской название Power Macintosh 6100 (с небольшими отличиями в зависимости '
                               'от скорости). Во второй находился привод CD-ROM. Дисковод гибких дисков располагался '
                               'вверху третьей части, а крошечная выпуклая кнопка питания — в её правом нижнем '
                               'углу.']}],
  'sources': [{'title': 'Apple: Power Macintosh 6100/60 — технические характеристики',
               'url': 'https://support.apple.com/kb/SP312?locale=en_US'},
              {'title': 'Apple-History: Power Macintosh 6100', 'url': 'https://apple-history.com/6100'},
              {'title': 'EveryMac: Power Macintosh 6100/60',
               'url': 'https://everymac.com/systems/apple/powermac/specs/powermac_6100_60.html'},
              {'title': 'Low End Mac: Power Mac 6100', 'url': 'https://lowendmac.com/1994/power-mac-6100/'}],
  'origin': {'title': 'Power Macintosh 6100 — Apple Wiki', 'url': 'https://apple.fandom.com/wiki/Power_Macintosh_6100'},
  'related': ['macintosh-quadra', 'macintosh-performa', 'power-mac-g3', 'mac'],
  'image': {'file': 'img/power-macintosh-6100.webp',
            'source': 'https://commons.wikimedia.org/wiki/File:Power_Macintosh_6100-60AV_-_front.jpg',
            'license': 'CC BY 2.0'}},
 {'slug': 'power-mac-g3',
  'title': 'Power Macintosh G3',
  'category': 'mac',
  'year': 1997,
  'emoji': '🖥️',
  'summary': 'Серия Macintosh на процессоре PowerPC G3, ставшая флагманом Apple.',
  'facts': {'Разработчик': 'Apple',
            'Тип': 'настольный компьютер',
            'Процессор': 'PowerPC G3 (PPC750) Motorola, 233, 266, 300 или 333 МГц',
            'Оперативная память': 'SDRAM PC66',
            'Накопитель': 'IDE',
            'Порты': 'SCSI, ADB, Ethernet 10Base-T, два последовательных порта',
            'Графика': 'ATI Rage II (позже Rage Pro)',
            'Предшественник': 'Power Macintosh 9600',
            'Преемник': 'Power Macintosh G3 (синий и белый)'},
  'body': ['Power Macintosh G3, позже называвшийся Power Mac G3, — серия компьютеров Macintosh от Apple на процессоре '
           'PowerPC G3 (PPC750).',
           'Крупным шагом вперёд стал большой кэш второго уровня на «задней шине» процессора: он уменьшил узкие места '
           'при передаче данных и позволил очень эффективно использовать скорость шины. Поэтому тогда Power Mac G3 '
           'считали более быстрыми, чем компьютеры Intel с похожей частотой процессора.',
           'Изначально Power Mac G3 задумывали как среднюю серию между недорогими Performa и LC и топовым Power '
           'Macintosh 9600. Но в ходе разработки стало ясно, что G3 намного быстрее Mac на PowerPC 604, и он стал '
           'флагманом.'],
  'sections': [{'title': 'Бежевые модели',
                'paragraphs': ['Первые «платиновые» Power Macintosh G3 (их обычно зовут «бежевыми») выпускались в трёх '
                               'вариантах: настольный корпус, прямо перешедший от Power Macintosh 7500; минитауэр на '
                               'основе уменьшенного корпуса Power Macintosh 8600; и новый моноблок Power Macintosh G3 '
                               'All-In-One с прозвищем «моляр».',
                               'Эти машины с процессорами PowerPC G3 от Motorola на 233, 266, 300 или 333 МГц работали '
                               'на шине 66 МГц с обычной памятью SDRAM PC66 и одними из первых Power Mac получили '
                               'жёсткие диски IDE. Звуковой схемы на логической плате не было: вместо этого в слот '
                               '«карты личности» ставили звуковую карту, а в AV-версиях — карту с захватом и выводом '
                               'S-Video. Теперь можно было заказать привод DVD-ROM, по-прежнему предлагались и приводы '
                               'Zip.',
                               'На плате были SCSI, ADB, Ethernet 10Base-T, два последовательных порта и графика ATI '
                               '(сначала Rage II, потом Rage Pro) со слотами для расширения VRAM. Три слота PCI и слот '
                               'внутреннего модема дополняли набор.']},
               {'title': 'Проблемы',
                'paragraphs': ['Некоторые ранние «платиновые» G3 не поддерживают подчинённые (slave) устройства на '
                               'контроллерах IDE, то есть на одну шину можно подключить только одно устройство (обычно '
                               'один оптический привод и один жёсткий диск). Проблему связали с логическими платами '
                               'ревизии A; в Mac OS X её нет.']},
               {'title': 'Синие и белые модели',
                'paragraphs': ['В начале 1999 года вышла переработанная серия Power Mac G3 в новом полупрозрачном '
                               'корпусе, известном как «синий и белый». Это была первая новая модель Power Macintosh '
                               'после iMac. Необычный корпус размещал логическую плату на откидной дверце, поэтому до '
                               'неё было легко добраться. Такой корпус использовали и во всех Power Mac G4, кроме '
                               'Cube. Подробнее — в статье о Power Macintosh G3 (синий и белый).']}],
  'sources': [{'title': 'Apple: Power Macintosh G3 (архив от 29 апреля 1998)',
               'url': 'https://web.archive.org/web/19980429142842/http://www.apple.com/powermac/g3/'},
              {'title': 'Apple: Power Macintosh G3 All-in-One (архив от 29 апреля 1998)',
               'url': 'https://web.archive.org/web/19980429143412/http://www.apple.com:80/powermac/g3/allinone/'},
              {'title': 'EveryMac: Power Macintosh G3',
               'url': 'https://everymac.com/systems/apple/powermac_g3/index-powermac-g3.html'},
              {'title': 'Low End Mac: Beige Power Mac G3 (1997)',
               'url': 'https://lowendmac.com/1997/beige-power-mac-g3-1997/'},
              {'title': 'Low End Mac: Beige Power Mac G3 All-in-One (1998)',
               'url': 'https://lowendmac.com/1998/beige-power-mac-g3-all-in-one/'},
              {'title': "Heise Online: Apple's New Macintosh G3 Range Tested in Practice (1999)",
               'url': 'https://web.archive.org/web/19991009150813/http://www.heise.de/ct/english/99/03/118/'}],
  'origin': {'title': 'Power Macintosh G3 — Apple Wiki', 'url': 'https://apple.fandom.com/wiki/Power_Macintosh_G3'},
  'related': ['power-macintosh-6100', 'power-mac-g3-bw', 'imac-g3', 'mac'],
  'image': {'file': 'img/power-mac-g3.webp',
            'source': 'https://commons.wikimedia.org/wiki/File:Macintosh_G3_DT.jpg',
            'license': 'CC BY-SA 2.5'}},
 {'slug': 'power-mac-g3-bw',
  'title': 'Power Macintosh G3 (синий и белый)',
  'category': 'mac',
  'year': 1999,
  'emoji': '🖥️',
  'summary': 'Переработанный Power Mac G3 1999 года в полупрозрачном сине-белом корпусе.',
  'facts': {'Кодовое название': 'Yosemite',
            'Разработчик': 'Apple',
            'Тип': 'настольный компьютер',
            'Представлен': '5 января 1999',
            'В продаже': '450 МГц — с 1 июня 1999',
            'Процессор': 'PowerPC G3 (медный, IBM), 300, 350, 400 или 450 МГц',
            'Графика': 'ATI Rage 128',
            'Оперативная память': 'до 1 ГБ, SDRAM PC100, шина 100 МГц',
            'Порты': '2 × FireWire, 2 × USB 1.1, ADB, Ethernet 100Base-TX',
            'Предшественник': 'Power Macintosh G3 («бежевый»)',
            'Преемник': 'Power Mac G4'},
  'body': ['Power Macintosh G3 в сине-белом корпусе с кодовым названием «Yosemite» (иногда его называют просто Power '
           'Mac G3) — переработанный преемник первой серии Power Macintosh G3, которую задним числом стали звать '
           '«бежевой».'],
  'sections': [{'title': 'Особенности',
                'paragraphs': ['Сине-белый G3 представили 5 января 1999 года на выставке Macworld Conference & Expo. '
                               'Это была первая новая модель Power Macintosh после iMac. Необычный корпус размещал '
                               'логическую плату на откидной дверце, поэтому доступ к ней был лёгким (такой корпус '
                               'использовали и во всех Power Mac G4, кроме Cube).',
                               'В этих моделях стояли новые медные процессоры PowerPC G3 производства IBM, которые '
                               'потребляли примерно в четыре раза меньше энергии, чем версии Motorola. Выпускались '
                               'варианты на 300, 350 и 400 МГц; версия на 450 МГц добавилась 1 июня 1999 года.',
                               'На логической плате было четыре слота PCI: три 64-разрядных на 33 МГц и один '
                               '32-разрядный на 66 МГц, отведённый под видеокарту ATI Rage 128. Четыре слота ОЗУ '
                               'принимали модули SDRAM PC100 (максимум 1 ГБ) и работали на шине 100 МГц. Встроенный '
                               'IDE обновили до Ultra ATA/33, а SCSI исчез: его заменили два порта FireWire. '
                               'Последовательных портов тоже не стало — вместо них появились два порта USB 1.1. Порт '
                               'ADB остался, как и возможность поставить внутренний модем. Ethernet 100Base-TX стал '
                               'стандартным, а звук вернулся на логическую плату.',
                               'Zip остался опцией, а в некоторые конфигурации входили привод DVD-ROM и дочерняя плата '
                               'декодера DVD-Video для видеокарты, обеспечивавшая аппаратное воспроизведение видео '
                               'DVD.',
                               'Сине-белый Power Mac G3 стал первым Power Mac с архитектурой «New World» на основе '
                               'Open Firmware и первым без встроенного SCSI. Поэтому поначалу многие покупатели '
                               'выбирали старые «платиновые» G3, чтобы сохранить совместимость с имевшимися '
                               'периферийными устройствами.']},
               {'title': 'Проблемы',
                'paragraphs': ['У ранних сине-белых G3 «ревизии 1» были проблемы с контроллером IDE: нельзя было '
                               'подключить два жёстких диска, а на дисках с более новыми платами контроллеров '
                               'возникали ошибки передачи данных. У «ревизии 2» контроллер IDE доработан: он позволяет '
                               'два диска и корректно работает с новыми дисками в пределах 28-разрядной адресации LBA. '
                               'Кроме того, в ревизии 2 есть кронштейн для двух дисков и обновлённая видеокарта.']}],
  'sources': [{'title': 'Apple: Power Macintosh G3 (архив от 8 мая 1999)',
               'url': 'https://web.archive.org/web/19990508065531/http://www.apple.com/powermac/'},
              {'title': 'Apple: PowerMac G3 (rev.1) — технические характеристики (архив от 22 апреля 1999)',
               'url': 'https://web.archive.org/web/19990422110257/http://www.apple.com/powermac/specs.html'},
              {'title': 'Apple: Power Macintosh G3 (Blue and White, rev.2) — технические характеристики',
               'url': 'https://support.apple.com/kb/SP133?viewlocale=en_US&locale=en_US'},
              {'title': 'EveryMac: Power Mac G3',
               'url': 'https://everymac.com/systems/apple/powermac_g3/index-powermac-g3.html'},
              {'title': 'EveryMac: как отличить ревизию 1 от ревизии 2 (2010)',
               'url': 'https://everymac.com/systems/apple/powermac_g3/faq/power-mac-g3-rev1-rev2-visual-differentiation-modem-usb-firewire.html'},
              {'title': 'Low End Mac: Blue and White Power Mac G3 (1999)',
               'url': 'https://lowendmac.com/1999/blue-and-white-power-mac-g3/'}],
  'origin': {'title': 'Power Macintosh G3 (Blue and White) — Apple Wiki',
             'url': 'https://apple.fandom.com/wiki/Power_Macintosh_G3_(Blue_and_White)'},
  'related': ['power-mac-g3', 'power-mac-g4', 'imac-g3', 'mac'],
  'image': {'file': 'img/power-mac-g3-bw.webp',
            'source': 'https://commons.wikimedia.org/wiki/File:The_%22Blue_%26_White%22_G3_system_(2378249113).jpg',
            'license': 'CC BY 2.0'}},
