                         'Wallstreet II / PDQ (сентябрь 1998): G3 233, 266 или 300 МГц; экран 14,1 дюйма, 1024×768; '
                         'ATI Rage Pro LT; память до 192 МБ (Apple) или 512 МБ; вес 3,5 кг',
                         'Lombard (май 1999): G3 333 или 400 МГц; 14,1 дюйма; память 64 МБ (до 384 МБ Apple или 512 '
                         'МБ); ATI Rage Pro LT с 8 МБ; диск 4–6 ГБ; CD-ROM 24× или DVD-ROM 2×; Ethernet 10/100; 2 '
                         'порта USB 1.1; вес 2,8 кг',
                         'Pismo (февраль 2000): G3 400 или 500 МГц; память 64 или 128 МБ (до 512 МБ Apple или 1 ГБ); '
