                         'Видеовыход: VGA у Kanga; VGA и S-Video у остальных',
                         'Максимальная система: Kanga — Mac OS 9.1 (9.2.2 с OS9Helper); Wallstreet и Wallstreet II — '
                         'Mac OS X 10.2.8 «Jaguar» (10.4.11 с XPostFacto); Lombard — 10.3.9 «Panther» (10.4.11 с '
