 {'slug': 'emac',
  'title': 'eMac',
  'category': 'mac',
  'year': 2002,
  'emoji': '🖥️',
  'summary': 'eMac («education Mac»): моноблок с 17-дюймовым плоским ЭЛТ-экраном и процессором G4, созданный для школ.',
  'facts': {'Разработчик': 'Apple Computer',
            'Тип': 'моноблок',
            'Представлен': '29 апреля 2002',
            'Снят с производства': '5 июля 2006',
            'Цена': 'от 1099 до 1499 долларов',
            'Процессор': 'PowerPC G4, от 700 МГц до 1,42 ГГц',
            'Графика': 'NVIDIA GeForce2 MX, затем ATI Radeon 7500 и Radeon 9200',
            'Экран': '17 дюймов (430 мм), плоский ЭЛТ',
            'Накопитель': 'жёсткий диск от 40 до 160 ГБ',
            'Система': 'Mac OS 9.2.2 и Mac OS X (с 10.1.4)',
            'Предшественник': 'iMac G3'},
  'body': ['eMac, сокращение от education Mac («Mac для образования»), — настольный Macintosh, который Apple выпустила '
           'в 2002 году. Сначала он предназначался для рынка образования, но позже его стали продавать как более '
           'дешёвую массовую альтернативу iMac G4 с ЖК-экраном.',
           'Дизайн eMac напоминает прежний iMac G3. По сравнению с первым iMac в eMac стоит процессор PowerPC G4, '
           'заметно быстрее прежних PowerPC G3, и 17-дюймовый плоский ЭЛТ-экран.',
           '12 октября 2005 года eMac сняли с розничной продажи, и дальше его продавали только учебным заведениям. 5 '
           'июля 2006 года Apple окончательно прекратила выпуск, а на смену пришёл более дешёвый базовый iMac, '
           'который, как и eMac, сначала продавали только учебным заведениям.'],
  'sections': [{'title': 'Обзор',
                'paragraphs': ['Apple представила eMac 29 апреля 2002 года как более дешёвую альтернативу недавно '
                               'вышедшему второму поколению iMac на G4 (при жизни его называли просто «новый iMac», а '
                               'после снятия с производства — iMac G4). Из-за ЖК-экрана новый iMac стоил заметно '
                               'дороже своего предшественника G3 с более дешёвым ЭЛТ-экраном, поэтому eMac считали '
                               'доступным вариантом для тех, кому нужно больше мощности, чем у первого iMac. '
                               'Изначально его предназначали только для образования, но спрос оказался так высок, что '
                               'через месяц eMac стали продавать в рознице. Тогда же появилась опциональная подставка '
                               'eMac Tilt and Swivel Stand.',
                               'В eMac стоял 17-дюймовый (430 мм) плоский ЭЛТ-монитор, процессор PowerPC G4 на 700 или '
                               '800 МГц, графика NVIDIA GeForce2 MX и встроенные стереодинамики по 18 Вт. Розничные '
                               'модели стоили 1099 и 1499 долларов, заполняя разрыв между iMac G3 за 799 долларов и '
                               'iMac G4 за 1499.',
                               'Выпуск iMac G3 прекратили в марте 2003 года, но на «дешёвое» место до мая 2003 года '
                               'Apple никого не ставила, пока не обновила eMac и не снизила цену до уровня старого '
                               'iMac. В этой ревизии частоты процессора составили 800 МГц и 1 ГГц, а GeForce2 MX '
                               'заменили видеокартой ATI Radeon 7500.',
                               'В октябре 2003 года eMac улучшили ещё раз: модель на 800 МГц убрали, а модель на 1 ГГц '
                               'подешевела. Более дорогая модель на 1 ГГц с SuperDrive тоже стала дешевле. Она была '
                               'одним из самых недорогих компьютеров известной марки, способных записывать DVD. Это же '
                               'стала последняя ревизия eMac, которая могла запускать Mac OS 9 нативно, и последняя '
                               'проданная модель Macintosh с такой возможностью.',
                               'Следующая ревизия вышла в апреле 2004 года: DDR SDRAM, более быстрый процессор на 1,25 '
                               'ГГц и лучший видеочип ATI Radeon 9200. Последняя ревизия появилась в мае 2005 года: '
                               'ещё более быстрый процессор на 1,42 ГГц, улучшенная графика и более ёмкие жёсткие '
                               'диски.',
                               '12 октября 2005 года Apple снова ограничила продажи eMac учебными заведениями и '
                               'вернулась к маркетинговой идее «E — значит Education». Причины не назывались. '
                               'Некоторые аналитики считали, что Apple хотела заставить широкую публику покупать более '
                               'дорогие Mac mini и iMac с более высокой маржой. Кроме того, eMac оставался '
                               'единственным ЭЛТ-продуктом в линейке Apple и выглядел громоздким рядом с новыми '
                               'компактными моделями с ЖК-экранами, а падение цен на ЖК-дисплеи постепенно снижало '
                               'цены на iMac G5. Тем не менее eMac по-прежнему можно было купить у сторонних '
                               'интернет-продавцов.',
                               '5 июля 2006 года всю линейку eMac сняли с производства. В тот же день появилась '
                               '«учебная конфигурация» iMac Core Duo: с приводом Combo вместо SuperDrive и жёстким '
                               'диском поменьше, 80 ГБ.',
                               'eMac изначально загружаются в Mac OS 9.2.2 и в Mac OS X, начиная с 10.1.4. За '
                               'исключением некоторых моделей на 1 ГГц без SuperDrive, модели на 1 ГГц и быстрее не '
                               'загружают OS 9, а eMac медленнее 1,0 ГГц официально не поддерживают 10.5 (требования: '
                               'G4 на 867 МГц и 512 МБ ОЗУ). Ни одна модель eMac не запускает OS X 10.6 «Snow Leopard» '
                               'и выше: для неё нужен процессор Intel.']},
               {'title': 'Технические проблемы',
                'paragraphs': ['У ряда eMac наблюдался так называемый «растровый сдвиг» (Raster Shift): нижняя треть '
                               'или половина экрана темнеет, а остальное изображение сдвигается вверх за край дисплея. '
                               'Появляются сильные помехи, и видимая часть экрана практически бесполезна. Apple '
                               'предложила решение — замену видеокабеля внутри корпуса eMac.',
                               'В начале 2006 года у некоторых владельцев eMac второй ревизии (им было около 18 '
                               'месяцев) начались зависания системы. Причина оказалась в бракованной партии '
                               'конденсаторов, которая вызывала неисправности и у iMac G5, и у многих других изделий '
                               'того же периода. В июне 2006 года Apple запустила программу ремонта eMac. Хотя она '
                               'напрямую относилась к проблеме конденсаторов, в списке симптомов программы «зависание» '
                               'не значилось. Apple согласилась продлить гарантию на этот дефект для eMac возрастом до '
                               '3 лет, но некоторые пользователи сообщали, что Apple принимает в ремонт и более старые '
                               'машины.']}],
  'sources': [{'title': 'Apple: eMac (архив 2002)',
               'url': 'https://web.archive.org/web/20020802103520/http://www.apple.com/emac/'},
              {'title': 'Apple: техническое описание eMac (2003)',
               'url': 'https://web.archive.org/web/20030607142528/https://store.apple.com/Catalog/uk/Images/emac_datasheet.pdf'}],
  'origin': {'title': 'EMac — Apple Wiki', 'url': 'https://apple.fandom.com/wiki/EMac'},
  'related': ['imac-g3', 'imac-g4', 'imac-g5', 'mac'],
  'image': {'file': 'img/emac.webp',
            'source': 'https://commons.wikimedia.org/wiki/File:Apple-eMac-FL_(transparent).png',
            'license': 'Public domain'}},
