                               'Однако у всех современных Mac есть порт Thunderbolt, и с отдельно продаваемым '
                               'переходником к нему можно подключить 30-дюймовый монитор.',
                               'Все Power Mac G5, 15- и 17-дюймовые PowerBook G4 и Mac Pro с середины 2006 до середины '
